#!/usr/bin/env python3
"""
Rebuilds every Appointments page in Hertility's structure, in FertiTerra branding.

Hertility's appointment pages all share one shape: hero, four trust badges, a
"Book a ..." intro with a booking card, what is included, who it is for, the
team, what you can talk about, a comparison, further reading, related services,
an FAQ and a closing block.

This writes one shared template plus the eight services behind it.

Routes rebuilt (old files backed up first):
  /appointments/advisor-call
  /appointments/hormone-symptom-consultation   (new)
  /appointments/ultrasound
  /appointments/gynaecologist
  /appointments/counselling
  /appointments/nutrition
  /appointments/menopause-specialist
  /appointments/skin-consultation

Prices are the ones already on your site. No other menu or page is touched.
"""
import base64
import json
from pathlib import Path

FILES = json.loads(base64.b64decode("").decode())
PAGES = json.loads(base64.b64decode("").decode())

MENU_OLD = '{ label: "Hormone and Symptom Consultation", href: "/consultation" }'
MENU_NEW = '{ label: "Hormone and Symptom Consultation", href: "/appointments/hormone-symptom-consultation" }'

TEMPLATE = '''import type { Metadata } from "next"
import { AppointmentPage } from "@/components/ft/appointment-page"

export const metadata: Metadata = {
  title: "%s | FertiTerra",
}

export default function Page() {
  return <AppointmentPage slug="%s" />
}
'''


def main():
    if not Path("package.json").is_file() or not Path("app").is_dir():
        print("Run this from the Fertiterra folder.")
        return

    print("1. Shared template")
    for rel, content in FILES.items():
        p = Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.is_file() and p.read_text(encoding="utf-8") == content:
            print("   already current: " + rel)
            continue
        p.write_text(content, encoding="utf-8")
        print("   wrote " + rel)

    print("")
    print("2. The eight appointment pages")
    for d, meta in PAGES.items():
        slug, title = meta
        p = Path(d)
        p.mkdir(parents=True, exist_ok=True)
        f = p / "page.tsx"
        body = TEMPLATE % (title, slug)
        if f.is_file():
            existing = f.read_text(encoding="utf-8")
            if existing == body:
                print("   already current: " + d)
                continue
            (p / "page.tsx.bak-before-appointment-rebuild").write_text(existing, encoding="utf-8")
        f.write_text(body, encoding="utf-8")
        print("   rebuilt " + d)

    print("")
    print("3. Menu entry for Hormone and Symptom Consultation")
    header = Path("components/header.tsx")
    if not header.is_file():
        print("   components/header.tsx not found, menu left alone")
    else:
        src = header.read_text(encoding="utf-8")
        if MENU_NEW in src:
            print("   already points at /appointments/hormone-symptom-consultation")
        elif MENU_OLD in src:
            header.with_suffix(".tsx.bak-before-appointment-menu").write_text(src, encoding="utf-8")
            header.write_text(src.replace(MENU_OLD, MENU_NEW), encoding="utf-8")
            print("   repointed to the new page")
        else:
            print("   entry not found, menu left alone (new page still works)")

    print("")
    print("Check it compiles:")
    print("   npx tsc --noEmit 2>&1 | grep appointments")
    print("")
    print("Then open:")
    for d in PAGES:
        print("   http://localhost:3000/" + d.replace("app/", ""))


if __name__ == "__main__":
    main()
